"""
Exhaustive Semantics Classifier for the Directed 3-Cycle.

Enumerates all 8 subsets of {0,1,2}, classifies each under the Dung semantics,
and confirms the 3-cycle has NO stable extension while the empty set is its
unique preferred extension.
"""
from __future__ import annotations
from itertools import combinations
from typing import Callable, FrozenSet, List

Attack = Callable[[int, int], bool]


def cycle3(a: int, b: int) -> bool:
    return b == (a + 1) % 3


def all_subsets(n: int) -> List[FrozenSet[int]]:
    return [frozenset(c) for k in range(n + 1) for c in combinations(range(n), k)]


def conflict_free(n: int, R: Attack, S: FrozenSet[int]) -> bool:
    return all(not R(a, b) for a in S for b in S)


def defends(n: int, R: Attack, S: FrozenSet[int], a: int) -> bool:
    return all(any(R(c, b) for c in S) for b in range(n) if R(b, a))


def admissible(n: int, R: Attack, S: FrozenSet[int]) -> bool:
    return conflict_free(n, R, S) and all(defends(n, R, S, a) for a in S)


def stable(n: int, R: Attack, S: FrozenSet[int]) -> bool:
    return conflict_free(n, R, S) and all(
        any(R(b, a) for b in S) for a in range(n) if a not in S
    )


def main() -> None:
    n = 3
    print(f"{'subset':<12}{'CF':<5}{'adm':<5}{'stable':<8}")
    for S in all_subsets(n):
        print(f"{str(set(S)) or '{}':<12}"
              f"{str(conflict_free(n, cycle3, S)):<5}"
              f"{str(admissible(n, cycle3, S)):<5}"
              f"{str(stable(n, cycle3, S)):<8}")
    stab = [S for S in all_subsets(n) if stable(n, cycle3, S)]
    adm = [S for S in all_subsets(n) if admissible(n, cycle3, S)]
    print(f"\n#stable = {len(stab)}   admissible sets = {[set(s) for s in adm]}")
    assert len(stab) == 0 and adm == [frozenset()]


if __name__ == "__main__":
    main()

"""
Stable Count vs. Euler Characteristic on Complete Conflict Graphs.

For the complete conflict graph on n arguments (everyone attacks everyone else,
no self-attacks) this verifies that the number of stable extensions equals n and
equals the Euler characteristic of the conflict-free complex, for n = 1..8.
"""
from __future__ import annotations
from itertools import combinations
from typing import Callable, FrozenSet, List

Attack = Callable[[int, int], bool]


def all_subsets(n: int) -> List[FrozenSet[int]]:
    return [frozenset(c) for k in range(n + 1) for c in combinations(range(n), k)]


def conflict_free(n: int, R: Attack, S: FrozenSet[int]) -> bool:
    return all(not R(a, b) for a in S for b in S)


def stable(n: int, R: Attack, S: FrozenSet[int]) -> bool:
    return conflict_free(n, R, S) and all(
        any(R(b, a) for b in S) for a in range(n) if a not in S
    )


def euler_characteristic(n: int, R: Attack) -> int:
    faces = [S for S in all_subsets(n) if S and conflict_free(n, R, S)]
    return sum((-1) ** (len(S) - 1) for S in faces)


def main() -> None:
    print(f"{'n':<4}{'#stable':<10}{'chi':<6}")
    for n in range(1, 9):
        def R(a: int, b: int) -> bool:
            return a != b
        cnt = sum(1 for S in all_subsets(n) if stable(n, R, S))
        chi = euler_characteristic(n, R)
        print(f"{n:<4}{cnt:<10}{chi:<6}")
        assert cnt == n == chi


if __name__ == "__main__":
    main()

"""
Randomized Existence Check for Symmetric Irreflexive Frameworks.

Draws random undirected loopless conflict graphs and confirms empirically that
every one admits at least one stable extension, and that its stable extensions
coincide exactly with its maximal conflict-free sets (maximal independent sets).
"""
from __future__ import annotations
from itertools import combinations
from typing import Callable, FrozenSet, List, Set, Tuple
import random

Attack = Callable[[int, int], bool]


def all_subsets(n: int) -> List[FrozenSet[int]]:
    return [frozenset(c) for k in range(n + 1) for c in combinations(range(n), k)]


def conflict_free(n: int, R: Attack, S: FrozenSet[int]) -> bool:
    return all(not R(a, b) for a in S for b in S)


def stable(n: int, R: Attack, S: FrozenSet[int]) -> bool:
    return conflict_free(n, R, S) and all(
        any(R(b, a) for b in S) for a in range(n) if a not in S
    )


def maximal_conflict_free(n: int, R: Attack, S: FrozenSet[int]) -> bool:
    if not conflict_free(n, R, S):
        return False
    return not any(
        a not in S and conflict_free(n, R, S | {a}) for a in range(n)
    )


def random_sym_irrefl(n: int, p: float, rng: random.Random) -> Attack:
    edges = {frozenset((a, b)) for a in range(n) for b in range(n)
             if a < b and rng.random() < p}

    def R(a: int, b: int) -> bool:
        return a != b and frozenset((a, b)) in edges

    return R


def canon(sets: List[FrozenSet[int]]) -> Set[Tuple[int, ...]]:
    return {tuple(sorted(s)) for s in sets}


def main(trials: int = 1000, max_n: int = 7) -> None:
    rng = random.Random(0)
    for _ in range(trials):
        n = rng.randint(1, max_n)
        R = random_sym_irrefl(n, rng.random(), rng)
        stab = [S for S in all_subsets(n) if stable(n, R, S)]
        mcf = [S for S in all_subsets(n) if maximal_conflict_free(n, R, S)]
        assert len(stab) >= 1, "existence must hold"
        assert canon(stab) == canon(mcf), "stable == maximal conflict-free"
    print(f"OK: {trials} random symmetric irreflexive frameworks "
          f"(n up to {max_n}) each had a stable extension,")
    print("and stable extensions coincided with maximal conflict-free sets.")


if __name__ == "__main__":
    main()

