from __future__ import annotations
from itertools import combinations
from typing import Callable, FrozenSet, List

Attack = Callable[[int, int], bool]


def enumerate_stable_extensions(n: int, attack: Attack) -> List[FrozenSet[int]]:
    """Return every stable extension of the framework (range(n), attack).

    A set S is stable iff it is conflict-free (no internal attack) and it
    attacks every argument outside S.  Complexity: O(2^n * n^2).
    """
    def conflict_free(S: FrozenSet[int]) -> bool:
        return all(not attack(a, b) for a in S for b in S)

    def dominates_outside(S: FrozenSet[int]) -> bool:
        return all(any(attack(b, a) for b in S) for a in range(n) if a not in S)

    result: List[FrozenSet[int]] = []
    for k in range(n + 1):
        for combo in combinations(range(n), k):
            S = frozenset(combo)
            if conflict_free(S) and dominates_outside(S):
                result.append(S)
    return result

from __future__ import annotations
from typing import Callable, FrozenSet, Set

Attack = Callable[[int, int], bool]


def greedy_maximal_conflict_free(n: int, attack: Attack) -> FrozenSet[int]:
    """Build an inclusion-maximal conflict-free set by greedy extension.

    Starting from the empty set, repeatedly add any argument that introduces no
    conflict (in either direction) with the current set nor with itself.  For a
    symmetric irreflexive framework the result is guaranteed to be a stable
    extension.  Complexity: O(n^2).
    """
    S: Set[int] = set()

    def compatible(a: int) -> bool:
        if attack(a, a):
            return False
        return all(not attack(a, b) and not attack(b, a) for b in S)

    for a in range(n):
        if compatible(a):
            S.add(a)
    return frozenset(S)

