from __future__ import annotations
from itertools import combinations
from typing import Callable, FrozenSet, List

Attack = Callable[[int, int], bool]


def preferred_extensions(n: int, attack: Attack) -> List[FrozenSet[int]]:
    """Return every preferred extension (maximal admissible set).

    First collect all admissible sets (conflict-free sets that defend every
    member), then keep those not properly contained in another admissible set.
    Complexity: O(2^n * n^2) for admissibility plus O(4^n) for the maximality
    filter (which can be reduced by sorting by size).
    """
    def conflict_free(S: FrozenSet[int]) -> bool:
        return all(not attack(a, b) for a in S for b in S)

    def defends(S: FrozenSet[int], a: int) -> bool:
        return all(any(attack(c, b) for c in S)
                   for b in range(n) if attack(b, a))

    def admissible(S: FrozenSet[int]) -> bool:
        return conflict_free(S) and all(defends(S, a) for a in S)

    adm: List[FrozenSet[int]] = []
    for k in range(n + 1):
        for combo in combinations(range(n), k):
            S = frozenset(combo)
            if admissible(S):
                adm.append(S)

    return [S for S in adm if not any(S < T for T in adm)]
